WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), islands AS (SELECT id, device_code, reading_ts, temp_c, status_bits, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, APPROX_PERCENTILE(temp_c, ARRAY(0.25, 0.5, 0.75)) AS temp_c_quartiles, ROUND(SUM(temp_c) / NULLIF(COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END), 0), 2) AS temp_c_per_dv_03, BIT_OR(status_bits) AS status_bits_bit_or, COUNT(DISTINCT device_code) AS distinct_device_codes, MIN(reading_ts) AS first_seen, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes FROM islands GROUP BY DATE_TRUNC('DAY', reading_ts)
